"""Multiple-choice quizzes: generated by the AI model from the notes, or drawn from the offline bank."""

import json
import logging
import random
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

from . import gamification, knowledge, languages
from .ai import AIService, AIUnavailable
from .db import now_iso
from .translation import TranslationError, Translator

log = logging.getLogger(__name__)

DIFFICULTIES = {"easy", "medium", "hard"}
COUNTS = {5, 10}

QUIZ_PROMPT = """You write multiple-choice quizzes for school students in India, based on the school's \
study notes below. Every question must be answerable from the notes, have exactly four options with exactly \
one correct answer, and avoid "all of the above" style options. Vary which option position is correct. \
Explanations are one or two encouraging sentences that teach why the answer is right. Don't use emoji. Write maths with \
LaTeX between $...$.

Reply with JSON only, in exactly this shape:
{"questions": [{"question": "...", "options": ["...", "...", "...", "..."], "answer_index": 0, "explanation": "..."}]}
where answer_index is the 0-based position of the correct option."""


class QuizError(Exception):
    pass


def _valid(question: dict) -> bool:
    options = question.get("options")
    return (
        isinstance(question.get("question"), str) and question["question"].strip()
        and isinstance(options, list) and len(options) == 4 and all(isinstance(o, str) and o.strip() for o in options)
        and isinstance(question.get("answer_index"), int) and 0 <= question["answer_index"] < 4
        and isinstance(question.get("explanation"), str)
    )


class QuizMaster:
    def __init__(self, ai: AIService, translator: Translator, content_dir: Path):
        self.ai = ai
        self.translator = translator
        self.bank_dir = content_dir / "quizzes"

    def _generate_ai(self, doc: dict, topic: str, count: int, difficulty: str, language: str) -> list[dict]:
        system = f'{QUIZ_PROMPT}\n\n<notes title="{doc["title"]}">\n{doc["body"]}\n</notes>'
        native = languages.LANGUAGES[language][1]
        focus = f"Focus on this topic: {topic}." if topic else "Cover a mix of topics from across the notes."
        prompt = (
            f"Write {count} {difficulty} questions for the {doc['title']} quiz. {focus} "
            f"Write the questions, options and explanations in {languages.english_name(language)} ({native})."
        )
        data = self.ai.generate_json(system, prompt)
        questions = [q for q in data.get("questions", []) if _valid(q)]
        if len(questions) < min(count, 3):
            raise AIUnavailable("The model returned too few valid questions")
        return questions[:count]

    def _bank(self, slug: str) -> list[dict]:
        path = self.bank_dir / f"{slug}.json"
        if not path.exists():
            return []
        return [q for q in json.loads(path.read_text(encoding="utf-8")) if _valid(q)]

    def _generate_offline(self, slug: str, topic: str, count: int, difficulty: str, language: str) -> list[dict]:
        bank = self._bank(slug)
        if not bank:
            raise QuizError("No quiz questions are available for this subject yet")
        pool = [q for q in bank if q.get("difficulty", "medium") == difficulty] or bank
        if topic:
            words = set(knowledge.tokenize(topic))
            matching = [q for q in pool if words & set(knowledge.tokenize(q["question"] + " " + q.get("topic", "")))]
            pool = matching or pool
        if len(pool) < count:
            pool = pool + [q for q in bank if q not in pool]
        questions = random.sample(pool, min(count, len(pool)))
        questions = [{k: q[k] for k in ("question", "options", "answer_index", "explanation")} for q in questions]
        # Shuffle option order so repeat quizzes don't always have the same answer position.
        for q in questions:
            order = list(range(4))
            random.shuffle(order)
            q["options"] = [q["options"][i] for i in order]
            q["answer_index"] = order.index(q["answer_index"])
        if language != "en":
            questions = self._translate(questions, language)
        return questions

    def _translate(self, questions: list[dict], language: str) -> list[dict]:
        strings = []
        for q in questions:
            strings.extend([q["question"], *q["options"], q["explanation"]])

        def one(text: str) -> str:
            try:
                return self.translator.translate(text, language, "en")[0]
            except TranslationError:
                return text

        with ThreadPoolExecutor(max_workers=8) as pool:
            translated = iter(list(pool.map(one, strings)))
        return [
            {"question": next(translated), "options": [next(translated) for _ in range(4)],
             "answer_index": q["answer_index"], "explanation": next(translated)}
            for q in questions
        ]

    def create(self, conn, user, subject: str, topic: str, count: int, difficulty: str, language: str) -> dict:
        doc = knowledge.get_document(conn, subject)
        if doc is None or doc["kind"] != "subject":
            raise QuizError("Unknown subject")
        if count not in COUNTS:
            count = 5
        if difficulty not in DIFFICULTIES:
            difficulty = "medium"
        topic = topic.strip()[:80]

        questions, engine = None, "library"
        if self.ai.available:
            try:
                questions, engine = self._generate_ai(doc, topic, count, difficulty, language), "ai"
            except AIUnavailable as exc:
                log.warning("AI quiz unavailable, using the question bank: %s", exc)
        if questions is None:
            questions = self._generate_offline(subject, topic, count, difficulty, language)

        cur = conn.execute(
            """INSERT INTO quizzes (user_id, subject, topic, language, difficulty, questions_json, answers_json,
                                    total, engine, created_at) VALUES (?, ?, ?, ?, ?, ?, '{}', ?, ?, ?)""",
            (user["id"], subject, topic or None, language, difficulty, json.dumps(questions, ensure_ascii=False),
             len(questions), engine, now_iso()),
        )
        conn.commit()
        return {
            "id": cur.lastrowid,
            "subject": subject,
            "subject_title": doc["title"],
            "topic": topic,
            "difficulty": difficulty,
            "engine": engine,
            "questions": [{"question": q["question"], "options": q["options"]} for q in questions],
        }

    def answer(self, conn, user, quiz_id: int, index: int, choice: int) -> dict:
        quiz = conn.execute("SELECT * FROM quizzes WHERE id = ? AND user_id = ?", (quiz_id, user["id"])).fetchone()
        if quiz is None:
            raise QuizError("Quiz not found")
        if quiz["completed_at"]:
            raise QuizError("This quiz is already finished")
        questions = json.loads(quiz["questions_json"])
        answers = json.loads(quiz["answers_json"] or "{}")
        if not (0 <= index < len(questions)) or not (0 <= choice < 4):
            raise QuizError("Invalid answer")
        if str(index) in answers:
            raise QuizError("You already answered this question")

        question = questions[index]
        answers[str(index)] = choice
        result = {
            "correct": choice == question["answer_index"],
            "answer_index": question["answer_index"],
            "explanation": question["explanation"],
        }
        conn.execute("UPDATE quizzes SET answers_json = ? WHERE id = ?", (json.dumps(answers), quiz_id))

        if len(answers) == len(questions):
            score = sum(1 for i, q in enumerate(questions) if answers.get(str(i)) == q["answer_index"])
            conn.execute("UPDATE quizzes SET score = ?, completed_at = ? WHERE id = ?", (score, now_iso(), quiz_id))
            reward = gamification.record_quiz(conn, user["id"], score, len(questions))
            xp_total = conn.execute("SELECT xp FROM users WHERE id = ?", (user["id"],)).fetchone()["xp"]
            result["finished"] = {
                "score": score,
                "total": len(questions),
                "xp_gained": reward["xp"],
                "badges": reward["badges"],
                "progress": gamification.level_info(xp_total),
            }
        conn.commit()
        return result
